{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.MoM_demand_plan_summaries as WITH meta_map AS ( SELECT UPPER( CASE WHEN UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\' THEN CASE WHEN POSITION(\'-\' IN REPLACE(SKU_GROUP, \' \', \'\')) > 0 AND SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) <> \'\' THEN SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) ELSE REPLACE(SKU_GROUP, \' \', \'\') END ELSE SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) END ) AS sku_group_clean, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ))) AS l1_category, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ))) AS category, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1), \'na\' ))) AS meta1, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2), \'na\' ))) AS meta2, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3), \'na\' ))) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ), demand AS ( SELECT LOWER(TRIM(l_1)) AS l1, LOWER(TRIM(category)) AS cat, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_3, \'na\'))) END AS meta3, CASE UPPER(month_raw) WHEN \'APRIL\' THEN \'Apr-26\' WHEN \'APR\' THEN \'Apr-26\' WHEN \'MAY\' THEN \'May-26\' WHEN \'JUNE\' THEN \'Jun-26\' WHEN \'JUN\' THEN \'Jun-26\' WHEN \'JULY\' THEN \'Jul-26\' WHEN \'JUL\' THEN \'Jul-26\' WHEN \'AUGUST\' THEN \'Aug-26\' WHEN \'AUG\' THEN \'Aug-26\' WHEN \'SEPTEMBER\' THEN \'Sep-26\' WHEN \'SEPT\' THEN \'Sep-26\' WHEN \'SEP\' THEN \'Sep-26\' WHEN \'OCTOBER\' THEN \'Oct-26\' WHEN \'OCT\' THEN \'Oct-26\' WHEN \'NOVEMBER\' THEN \'Nov-26\' WHEN \'NOV\' THEN \'Nov-26\' WHEN \'DECEMBER\' THEN \'Dec-26\' WHEN \'DEC\' THEN \'Dec-26\' WHEN \'JANUARY\' THEN \'Jan-27\' WHEN \'JAN\' THEN \'Jan-27\' WHEN \'FEBRUARY\' THEN \'Feb-27\' WHEN \'FEB\' THEN \'Feb-27\' END AS month, \'2. Demand\' AS metrics, COALESCE(TRY_TO_NUMBER(REPLACE(value::STRING, \',\', \'\')), 0) AS value FROM snitch_db.maplemonk.demand_requirement_r_Demand_Requirment UNPIVOT ( value FOR month_raw IN ( April, May, June, July, August, September, October, November, December, January, February ) ) ), closing_stock AS ( SELECT LOWER(TRIM(l_1)) AS l1, LOWER(TRIM(category)) AS cat, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_3, \'na\'))) END AS meta3, CASE UPPER(month_raw) WHEN \'APRIL\' THEN \'Apr-26\' WHEN \'APR\' THEN \'Apr-26\' WHEN \'MAY\' THEN \'May-26\' WHEN \'JUNE\' THEN \'Jun-26\' WHEN \'JUN\' THEN \'Jun-26\' WHEN \'JULY\' THEN \'Jul-26\' WHEN \'JUL\' THEN \'Jul-26\' WHEN \'AUGUST\' THEN \'Aug-26\' WHEN \'AUG\' THEN \'Aug-26\' WHEN \'SEPTEMBER\' THEN \'Sep-26\' WHEN \'SEPT\' THEN \'Sep-26\' WHEN \'SEP\' THEN \'Sep-26\' WHEN \'OCTOBER\' THEN \'Oct-26\' WHEN \'OCT\' THEN \'Oct-26\' WHEN \'NOVEMBER\' THEN \'Nov-26\' WHEN \'NOV\' THEN \'Nov-26\' WHEN \'DECEMBER\' THEN \'Dec-26\' WHEN \'DEC\' THEN \'Dec-26\' WHEN \'JANUARY\' THEN \'Jan-27\' WHEN \'JAN\' THEN \'Jan-27\' WHEN \'FEBRUARY\' THEN \'Feb-27\' WHEN \'FEB\' THEN \'Feb-27\' END AS month, \'1. Closing Stock\' AS metrics, COALESCE(TRY_TO_NUMBER(REPLACE(value::STRING, \',\', \'\')), 0) AS value FROM snitch_db.maplemonk.demand_requirement_r_closing_stock UNPIVOT ( value FOR month_raw IN ( April, May, June, July, August, September, October, November, December, January, February ) ) ), online_sales AS ( SELECT LOWER(TRIM(l_1)) AS l1, LOWER(TRIM(category)) AS cat, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_3, \'na\'))) END AS meta3, CASE UPPER(month_raw) WHEN \'APRIL\' THEN \'Apr-26\' WHEN \'APR\' THEN \'Apr-26\' WHEN \'MAY\' THEN \'May-26\' WHEN \'JUNE\' THEN \'Jun-26\' WHEN \'JUN\' THEN \'Jun-26\' WHEN \'JULY\' THEN \'Jul-26\' WHEN \'JUL\' THEN \'Jul-26\' WHEN \'AUGUST\' THEN \'Aug-26\' WHEN \'AUG\' THEN \'Aug-26\' WHEN \'SEPTEMBER\' THEN \'Sep-26\' WHEN \'SEPT\' THEN \'Sep-26\' WHEN \'SEP\' THEN \'Sep-26\' WHEN \'OCTOBER\' THEN \'Oct-26\' WHEN \'OCT\' THEN \'Oct-26\' WHEN \'NOVEMBER\' THEN \'Nov-26\' WHEN \'NOV\' THEN \'Nov-26\' WHEN \'DECEMBER\' THEN \'Dec-26\' WHEN \'DEC\' THEN \'Dec-26\' WHEN \'JANUARY\' THEN \'Jan-27\' WHEN \'JAN\' THEN \'Jan-27\' WHEN \'FEBRUARY\' THEN \'Feb-27\' WHEN \'FEB\' THEN \'Feb-27\' END AS month, \'7. Online Sales\' AS metrics, COALESCE(TRY_TO_NUMBER(REPLACE(value::STRING, \',\', \'\')), 0) AS value FROM snitch_db.maplemonk.demand_requirement_r_online_sales UNPIVOT ( value FOR month_raw IN ( Apr, May, June, July, Aug, Sept, Oct, Nov, Dec, Jan, Feb ) ) ), offline_sales AS ( SELECT LOWER(TRIM(l_1)) AS l1, LOWER(TRIM(category)) AS cat, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_3, \'na\'))) END AS meta3, CASE UPPER(month_raw) WHEN \'APRIL\' THEN \'Apr-26\' WHEN \'APR\' THEN \'Apr-26\' WHEN \'MAY\' THEN \'May-26\' WHEN \'JUNE\' THEN \'Jun-26\' WHEN \'JUN\' THEN \'Jun-26\' WHEN \'JULY\' THEN \'Jul-26\' WHEN \'JUL\' THEN \'Jul-26\' WHEN \'AUGUST\' THEN \'Aug-26\' WHEN \'AUG\' THEN \'Aug-26\' WHEN \'SEPTEMBER\' THEN \'Sep-26\' WHEN \'SEPT\' THEN \'Sep-26\' WHEN \'SEP\' THEN \'Sep-26\' WHEN \'OCTOBER\' THEN \'Oct-26\' WHEN \'OCT\' THEN \'Oct-26\' WHEN \'NOVEMBER\' THEN \'Nov-26\' WHEN \'NOV\' THEN \'Nov-26\' WHEN \'DECEMBER\' THEN \'Dec-26\' WHEN \'DEC\' THEN \'Dec-26\' WHEN \'JANUARY\' THEN \'Jan-27\' WHEN \'JAN\' THEN \'Jan-27\' WHEN \'FEBRUARY\' THEN \'Feb-27\' WHEN \'FEB\' THEN \'Feb-27\' END AS month, \'8. Offline Sales\' AS metrics, COALESCE(TRY_TO_NUMBER(REPLACE(value::STRING, \',\', \'\')), 0) AS value FROM snitch_db.maplemonk.demand_requirement_r_offline_sales UNPIVOT ( value FOR month_raw IN ( Apr, May, June, July, Aug, Sept, Oct, Nov, Dec, Jan, Feb ) ) ), pipeline_base AS ( SELECT LOWER(TRIM(mm.l1_category)) AS l1, LOWER(TRIM(mm.category)) AS cat, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta3, \'na\'))) END AS meta3, CASE WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-04-01\' THEN \'Apr-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-05-01\' THEN \'May-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-06-01\' THEN \'Jun-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-07-01\' THEN \'Jul-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-08-01\' THEN \'Aug-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-09-01\' THEN \'Sep-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-10-01\' THEN \'Oct-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-11-01\' THEN \'Nov-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2026-12-01\' THEN \'Dec-26\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2027-01-01\' THEN \'Jan-27\' WHEN DATE_TRUNC(\'MONTH\', p.fdd)::DATE = DATE \'2027-02-01\' THEN \'Feb-27\' END AS month, CASE WHEN UPPER(TRIM(p.repeat)) = \'REPEAT\' THEN \'4. Repeat - Pipeline\' ELSE \'5. New - Pipeline\' END AS pipeline_split, SUM(COALESCE(TRY_TO_NUMBER(REPLACE(p.qty::STRING, \',\', \'\')), 0)) AS value FROM snitch_db.maplemonk.production_pipeline_data p LEFT JOIN meta_map mm ON mm.sku_group_clean = UPPER( CASE WHEN UPPER(REPLACE(p.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(p.sku_group, \' \', \'\')) LIKE \'4C-%\' THEN CASE WHEN POSITION(\'-\' IN REPLACE(p.sku_group, \' \', \'\')) > 0 AND SPLIT_PART(REPLACE(p.sku_group, \' \', \'\'), \'-\', 2) <> \'\' THEN SPLIT_PART(REPLACE(p.sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(p.sku_group, \' \', \'\'), \'-\', 2) ELSE REPLACE(p.sku_group, \' \', \'\') END ELSE SPLIT_PART(REPLACE(p.sku_group, \' \', \'\'), \'-\', 1) END ) WHERE DATE_TRUNC(\'MONTH\', p.fdd)::DATE BETWEEN DATE \'2026-04-01\' AND DATE \'2027-02-01\' GROUP BY 1,2,3,4,5,6,7 ), pipeline AS ( SELECT l1, cat, meta1, meta2, meta3, month, \'3. Pipeline\' AS metrics, SUM(value) AS value FROM pipeline_base GROUP BY 1,2,3,4,5,6 ), new_repeat_pipeline AS ( SELECT l1, cat, meta1, meta2, meta3, month, pipeline_split AS metrics, SUM(value) AS value FROM pipeline_base GROUP BY 1,2,3,4,5,6,7 ), po_raised AS ( SELECT LOWER(TRIM(mm.l1_category)) AS l1, LOWER(TRIM(mm.category)) AS cat, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta3, \'na\'))) END AS meta3, CASE WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-04-01\' THEN \'Apr-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-05-01\' THEN \'May-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-06-01\' THEN \'Jun-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-07-01\' THEN \'Jul-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-08-01\' THEN \'Aug-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-09-01\' THEN \'Sep-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-10-01\' THEN \'Oct-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-11-01\' THEN \'Nov-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2026-12-01\' THEN \'Dec-26\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2027-01-01\' THEN \'Jan-27\' WHEN DATE_TRUNC(\'MONTH\', po.edd)::DATE = DATE \'2027-02-01\' THEN \'Feb-27\' END AS month, \'6. PO Raised Already\' AS metrics, SUM(COALESCE(TRY_TO_NUMBER(REPLACE(po.total_qty::STRING, \',\', \'\')), 0)) AS value FROM snitch_db.maplemonk.logic_purchase_order po LEFT JOIN meta_map mm ON mm.sku_group_clean = UPPER( CASE WHEN UPPER(REPLACE(COALESCE(po.sku_group, po.sku), \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(COALESCE(po.sku_group, po.sku), \' \', \'\')) LIKE \'4C-%\' THEN CASE WHEN POSITION(\'-\' IN REPLACE(COALESCE(po.sku_group, po.sku), \' \', \'\')) > 0 AND SPLIT_PART(REPLACE(COALESCE(po.sku_group, po.sku), \' \', \'\'), \'-\', 2) <> \'\' THEN SPLIT_PART(REPLACE(COALESCE(po.sku_group, po.sku), \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(COALESCE(po.sku_group, po.sku), \' \', \'\'), \'-\', 2) ELSE REPLACE(COALESCE(po.sku_group, po.sku), \' \', \'\') END ELSE SPLIT_PART(REPLACE(COALESCE(po.sku_group, po.sku), \' \', \'\'), \'-\', 1) END ) WHERE DATE_TRUNC(\'MONTH\', po.edd)::DATE BETWEEN DATE \'2026-04-01\' AND DATE \'2027-02-01\' GROUP BY 1,2,3,4,5,6 ), final AS ( SELECT * FROM closing_stock UNION ALL SELECT * FROM demand UNION ALL SELECT * FROM pipeline UNION ALL SELECT * FROM po_raised UNION ALL SELECT * FROM new_repeat_pipeline UNION ALL SELECT * FROM online_sales UNION ALL SELECT * FROM offline_sales ) SELECT l1 AS \"L1\", cat AS \"Cat\", meta1 AS \"Meta 1\", meta2 AS \"Meta 2\", meta3 AS \"Meta 3\", month AS \"Month\", CASE \"Month\" WHEN \'Apr-26\' THEN 1 WHEN \'May-26\' THEN 2 WHEN \'Jun-26\' THEN 3 WHEN \'Jul-26\' THEN 4 WHEN \'Aug-26\' THEN 5 WHEN \'Sep-26\' THEN 6 WHEN \'Oct-26\' THEN 7 WHEN \'Nov-26\' THEN 8 WHEN \'Dec-26\' THEN 9 WHEN \'Jan-27\' THEN 10 WHEN \'Feb-27\' THEN 11 ELSE 99 END Monthv1, metrics AS \"Metrics\", SUM(COALESCE(value, 0)) AS \"Value\" FROM final WHERE month IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8 ORDER BY \"L1\", \"Cat\", \"Meta 1\", \"Meta 2\", \"Meta 3\", CASE \"Month\" WHEN \'Apr-26\' THEN 1 WHEN \'May-26\' THEN 2 WHEN \'Jun-26\' THEN 3 WHEN \'Jul-26\' THEN 4 WHEN \'Aug-26\' THEN 5 WHEN \'Sep-26\' THEN 6 WHEN \'Oct-26\' THEN 7 WHEN \'Nov-26\' THEN 8 WHEN \'Dec-26\' THEN 9 WHEN \'Jan-27\' THEN 10 WHEN \'Feb-27\' THEN 11 ELSE 99 END, \"Metrics\" ;",
